contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: receiver to send to, amount to attempt to transfer
    function run(address payable receiver, uint256 amount) public payable {
        require(true);
        // record balance of contract before the call
        uint256 before = address(c).balance;

        // Attempt the call and capture whether it reverted
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General rule: If call did not revert, then msg.sender must have been owner (i.e. this contract is owner)
        // and the contract's balance decreased by exactly 'amount' (unless amount > before which would revert).
        // If call reverted, the contract balance must be unchanged.
        // We cannot directly read owner, but since c was deployed fresh by the checker and the InvMutTest
        // contract is the caller of sendTo, a successful non-reverting call implies this contract was owner.

        assert(
            (reverted && after == before) || (!reverted && before >= amount && after == before - amount)
        );
    }

    receive() external payable {}
}

