    // single public function: callerAddr is the address that will be used as msg.sender for the test's external call
    // We cannot change msg.sender for calls into C from this contract, so to simulate non-owner we rely on the fact
    // that the owner of freshly deployed C is this InvMutTest contract; therefore a non-owner call must be made by
    // some externally owned account — but the checker will only call run once from an external EOA. To ensure that
    // we test the non-owner behavior, require that the external caller of run is NOT address(this).
    // The function takes a receiver and amount and attempts to invoke c.sendTo via try/catch to observe revert.
    function run(address payable receiver, uint256 amount) public payable {
        // Ensure the external caller is not this contract so that msg.sender for this run is a non-owner EOA
        require(msg.sender != address(this));

        // Record contract balance before the call
        uint256 before = address(c).balance;

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General rule: when invoked by a non-owner (which is the case because msg.sender != address(this)),
        // sendTo must revert and must not change the contract's balance.
        assert(reverted && after == before);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // try to call sendTo from this contract (which is the deployer/owner) and from an external address simulated via address(this).balance changes
    // We take params: receiver and amount and an address otherCaller represented by sending funds through a low-level call from that address is not possible here,
    // but we can check two executions: one where this contract (the owner) calls sendTo, and one where a non-owner attempt is detected by using try/catch when forwarding via a call to c from this contract after transferring ownership is impossible to simulate.
    // Instead, we assert a general invariant: if a sendTo call from this contract (the owner) does not revert then C's balance decreases by amount; and if it reverts then balance is unchanged.

    // We expose parameters: receiver and amount. The test will perform the owner call and observe revert flag and balances.
    function run(address payable receiver, uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // read balance before
        uint256 before = address(c).balance;

        // perform the call as owner (this contract is the deployer/owner of c)
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General rule: if the call reverted then contract balance must be unchanged; if it didn't revert then balance decreased by at most amount (i.e., either decreased exactly by amount or by less if transfer failed due to receiver fallback consuming gas — but transfer uses transfer so it either succeeds sending amount or reverts). We assert a precise relation: not reverted => after + amount == before; reverted => after == before.
        assert((!reverted && after + amount == before) || (reverted && after == before));
    }

    receive() external payable {}
}

