contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // msg.sender for calls to c will be this contract; we model two cases by passing
    // a boolean: if true, attempt the transfer as owner (which is deployer of c, i.e., this contract),
    // otherwise attempt as a non-owner by calling via address different from this contract using low-level call.
    // amount is the value to attempt transferring from c to receiver.
    function run(address payable receiver, uint amount, bool callAsOwner) public payable {
        require(receiver != address(0));
        // Fund the c contract so it can transfer out 'amount' if allowed.
        // We must have this contract hold enough balance to fund c.
        require(msg.value >= amount);
        // Send funds to c so it has balance to transfer
        (bool sentToC,) = address(c).call{value: amount}("");
        require(sentToC);

        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceReceiver = address(receiver).balance;

        bool reverted;
        if (callAsOwner) {
            // When calling as owner: this contract is the owner (deployer of C), so call directly.
            reverted = false;
            try c.sendTo(receiver, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // When calling as non-owner: perform a low-level call from a different address by using a contract-created call proxy.
            // We create a tiny helper contract that calls c.sendTo; creation returns new address which is non-owner.
            NonOwnerCaller proxy = new NonOwnerCaller(c);
            try proxy.callSendTo(receiver, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterBalanceC = address(c).balance;
        uint afterBalanceReceiver = address(receiver).balance;

        // General rule:
        // - If callAsOwner == true then sendTo must NOT revert, and c's balance must decrease by amount and receiver's balance increase by amount.
        // - If callAsOwner == false then sendTo must revert and neither c's nor receiver's balances change.
        assert(
            (callAsOwner && !reverted && afterBalanceC + amount == beforeBalanceC && afterBalanceReceiver == beforeBalanceReceiver + amount)
            ||
            (!callAsOwner && reverted && afterBalanceC == beforeBalanceC && afterBalanceReceiver == beforeBalanceReceiver)
        );
    }

    receive() external payable {}
}

// Minimal helper contract to call c.sendTo from a different address (non-owner)
contract NonOwnerCaller {
    C c;
    constructor(C _c) payable { c = _c; }
    function callSendTo(address receiver, uint amount) public {
        c.sendTo(receiver, amount);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Attempt to drive c.sendTo and assert conservation of funds or no-change on revert.
    // Parameters:
    //  - receiver: destination of the transfer
    //  - fundAmount: amount to pre-fund C with (sent to C from this contract before calling sendTo)
    //  - sendAmount: amount passed to c.sendTo
    function run(address payable receiver, uint fundAmount, uint sendAmount) public payable {
        require(receiver != address(0));
        // Ensure this test contract has enough balance to fund C
        require(address(this).balance >= fundAmount);

        // Fund C so it may have funds to send
        (bool funded, ) = address(c).call{value: fundAmount}("");
        require(funded);

        uint beforeC = address(c).balance;
        uint beforeReceiver = receiver.balance;

        bool reverted;
        try c.sendTo(receiver, sendAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterReceiver = receiver.balance;

        // General rule:
        // - If sendTo reverted, neither C's balance nor receiver's balance changed.
        // - If sendTo did not revert, Ether is conserved: (afterC + afterReceiver) == (beforeC + beforeReceiver).
        assert(
            (reverted && afterC == beforeC && afterReceiver == beforeReceiver)
            ||
            (!reverted && afterC + afterReceiver == beforeC + beforeReceiver)
        );
    }

    receive() external payable {}
}

